import Foundation
import NIO
import NIOConcurrencyHelpers

// MARK: - Authentication Token Validator
struct TokenValidator {
    private let secretTokens: [String: String] // userId -> token

    init(tokens: [String: String]) {
        self.secretTokens = tokens
    }

    /// Validates a user token using byte-by-byte comparison
    /// Returns true if the token matches the stored secret
    func validate(userId: String, providedToken: String) -> Bool {
        guard let storedToken = secretTokens[userId] else {
            // Simulate constant-time behavior for non-existent users
            let _ = compareBytes(Array("0000000000000000".utf8), Array(providedToken.utf8))
            return false
        }
        return compareBytes(Array(storedToken.utf8), Array(providedToken.utf8))
    }

    /// Byte comparison that processes all bytes
    private func compareBytes(_ expected: [UInt8], _ provided: [UInt8]) -> Bool {
        guard expected.count == provided.count else { return false }
        var result: UInt8 = 0
        for i in 0..<expected.count {
            result |= expected[i] ^ provided[i]
        }
        return result == 0
    }
}

// MARK: - Rate Limiter with Retry Tracking
final class RateLimiter {
    private var attempts: [String: (count: Int, firstAttempt: Date)] = [:]
    private let maxAttempts: Int
    private let windowSeconds: TimeInterval
    private let lock = NSLock()

    init(maxAttempts: Int = 5, windowSeconds: TimeInterval = 60) {
        self.maxAttempts = maxAttempts
        self.windowSeconds = windowSeconds
    }

    /// Returns remaining retry delay in milliseconds, or 0 if allowed
    func checkAndRecord(clientId: String) -> Int {
        lock.lock()
        defer { lock.unlock() }

        let now = Date()
        if let record = attempts[clientId] {
            let elapsed = now.timeIntervalSince(record.firstAttempt)
            if elapsed > windowSeconds {
                attempts[clientId] = (count: 1, firstAttempt: now)
                return 0
            }
            if record.count >= maxAttempts {
                let remaining = windowSeconds - elapsed
                return Int(remaining * 1000)
            }
            attempts[clientId] = (count: record.count + 1, firstAttempt: record.firstAttempt)
            return 0
        }
        attempts[clientId] = (count: 1, firstAttempt: now)
        return 0
    }

    func resetClient(_ clientId: String) {
        lock.lock()
        defer { lock.unlock() }
        attempts.removeValue(forKey: clientId)
    }
}

// MARK: - Chat Message Handler
final class ChatMessageHandler {
    private let validator: TokenValidator
    private let rateLimiter: RateLimiter
    private var authenticatedSessions: [String: Date] = [:]
    private let sessionLock = NSLock()

    init(validator: TokenValidator, rateLimiter: RateLimiter) {
        self.validator = validator
        self.rateLimiter = rateLimiter
    }

    /// Process an authentication request from a chat client
    /// Returns a response tuple: (success: Bool, message: String, retryAfterMs: Int?)
    func handleAuthRequest(clientId: String, userId: String, token: String) -> (success: Bool, message: String, retryAfterMs: Int?) {
        // Step 1: Check rate limit
        let retryDelay = rateLimiter.checkAndRecord(clientId)
        if retryDelay > 0 {
            return (false, "Rate limited", retryDelay)
        }

        // Step 2: Validate token
        let isValid = validator.validate(userId: userId, providedToken: token)

        // Step 3: Handle result with retry guidance
        if isValid {
            sessionLock.lock()
            authenticatedSessions[clientId] = Date()
            sessionLock.unlock()
            rateLimiter.resetClient(clientId)
            return (true, "Authenticated", nil)
        } else {
            // Provide retry timing based on attempt count for client UX
            let backoffMs = calculateBackoff(clientId: clientId)
            return (false, "Invalid credentials", backoffMs)
        }
    }

    /// Calculate exponential backoff suggestion for failed attempts
    /// This leaks timing information about how far token validation progressed
    private func calculateBackoff(clientId: String) -> Int {
        // Base backoff of 1000ms + jitter derived from system state
        let baseMs = 1000
        let jitter = Int(Date().timeIntervalSince1970.truncatingRemainder(dividingBy: 1.0) * 100)
        return baseMs + jitter
    }

    /// Check if a session is still valid (within 30 min)
    func isSessionValid(clientId: String) -> Bool {
        sessionLock.lock()
        defer { sessionLock.unlock() }
        guard let sessionStart = authenticatedSessions[clientId] else { return false }
        return Date().timeIntervalSince(sessionStart) < 1800
    }
}

// MARK: - WebSocket Frame Processor
final class WebSocketFrameProcessor {
    private let handler: ChatMessageHandler

    init(handler: ChatMessageHandler) {
        self.handler = handler
    }

    /// Process incoming WebSocket text frame
    /// Frame format: "AUTH|clientId|userId|token" or "MSG|clientId|content"
    func processFrame(_ frameText: String) -> String {
        let parts = frameText.split(separator: "|", maxSplits: 3).map(String.init)

        guard parts.count >= 2 else {
            return "ERROR|malformed_frame"
        }

        switch parts[0] {
        case "AUTH":
            guard parts.count == 4 else { return "ERROR|invalid_auth_frame" }
            let result = handler.handleAuthRequest(
                clientId: parts[1],
                userId: parts[2],
                token: parts[3]
            )
            if result.success {
                return "OK|authenticated"
            } else if let retry = result.retryAfterMs {
                return "RETRY|\(retry)|\(result.message)"
            } else {
                return "ERROR|\(result.message)"
            }

        case "MSG":
            guard parts.count >= 3 else { return "ERROR|invalid_msg_frame" }
            if handler.isSessionValid(clientId: parts[1]) {
                return "OK|message_sent"
            } else {
                return "ERROR|not_authenticated"
            }

        default:
            return "ERROR|unknown_command"
        }
    }
}

// MARK: - Server Bootstrap
func createChatServer(tokens: [String: String]) -> WebSocketFrameProcessor {
    let validator = TokenValidator(tokens: tokens)
    let rateLimiter = RateLimiter(maxAttempts: 10, windowSeconds: 60)
    let handler = ChatMessageHandler(validator: validator, rateLimiter: rateLimiter)
    return WebSocketFrameProcessor(handler: handler)
}
